import React from "react";

const baseURL="http://moreshop.co.in:8000"

const config={
    siteURL:"moreshop.co.in:8000",
    apiBaseURL:`${baseURL}/api/v1`,
    staticBaseURL:`${baseURL}`,
    apiTimeout: 500000
}
export default config;
